#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
NOTIFS="$ROOT/components/notifications/Notifications.qml"
SHELL="$ROOT/shell.qml"
fail() { echo "FAIL: $*" >&2; exit 1; }
[[ -f "$NOTIFS" ]] || fail 'notification component missing'
grep -Fq 'import Quickshell.Services.Notifications' "$NOTIFS" || fail 'notification service import missing'
grep -Fq 'NotificationServer {' "$NOTIFS" || fail 'NotificationServer missing'
grep -Fq 'notification.tracked = true' "$NOTIFS" || fail 'incoming notifications are not tracked'
grep -Fq 'notificationServer.trackedNotifications' "$NOTIFS" || fail 'tracked notification queue is not rendered'
grep -Fq 'readonly property int visibleNotificationCount: visibleNotificationModel.values.length' "$NOTIFS" || fail 'popup visibility must use the filtered visible count'
grep -Fq 'ScriptModel {' "$NOTIFS" || fail 'visible tracked notifications must pass through ScriptModel'
grep -Fq 'NotificationDnd.visibleNotifications(' "$NOTIFS" || fail 'DND-suppressed notifications must be removed from the toast model'
grep -Fq 'notificationList.contentHeight' "$NOTIFS" || fail 'popup height must follow actual ListView content height'
grep -Fq 'screen.height - root.notificationCoordinate(1) - 16' "$NOTIFS" || fail 'popup height must be capped to screen height'
if grep -Fq 'notificationServer.trackedNotifications.count' "$NOTIFS"; then fail 'ObjectModel has no count property; use values.length'; fi
grep -Fq 'card.notification.expire()' "$NOTIFS" || fail 'notification timeout handling missing'
grep -Fq 'card.notification.dismiss()' "$NOTIFS" || fail 'notification dismiss handling missing'
grep -Fq 'card.defaultAction.invoke()' "$NOTIFS" || fail 'default notification action remains available on card click'
grep -Fq 'id: actionRow' "$NOTIFS" && fail 'application action buttons must not be rendered'
grep -Fq 'active: Settings.loaded' "$SHELL" || fail 'NotificationServer bridge must remain loaded after settings initialize'
grep -Fq 'process-wide C++ singleton' "$SHELL" || fail 'shell must document process-wide D-Bus server lifetime'
grep -Fq 'notificationSurfaceActive: notificationsModuleEnabled' "$NOTIFS" || fail 'disabled module must hide the notification surface'
grep -Fq 'if (!root.notificationsModuleEnabled || !notification) return false' "$NOTIFS" || fail 'disabled module must reject new notifications'
grep -Fq 'root.dismissTrackedNotifications()' "$NOTIFS" || fail 'disabling module must dismiss already tracked notifications'
grep -Fq 'keepOnReload: true' "$NOTIFS" || fail 'tracked notifications must survive shell reloads'
grep -Fq 'Instantiator {' "$NOTIFS" || fail 'tracked notification properties must be observed for replacements'
grep -Fq 'function onSummaryChanged() { root.scheduleTrackedNotificationRefresh(modelData) }' "$NOTIFS" || fail 'replaced notification summaries must refresh history'
grep -Fq 'function onBodyChanged() { root.scheduleTrackedNotificationRefresh(modelData) }' "$NOTIFS" || fail 'replaced notification bodies must refresh history'
grep -Fq 'function onDesktopEntryChanged() { root.scheduleTrackedNotificationRefresh(modelData) }' "$NOTIFS" || fail 'replaced sender desktop IDs must refresh DND catalog'
grep -Fq 'function onAppNameChanged() { root.scheduleTrackedNotificationRefresh(modelData) }' "$NOTIFS" || fail 'replaced sender names must refresh DND catalog'
grep -Fq 'function onActionsChanged() { root.scheduleTrackedNotificationRefresh(modelData) }' "$NOTIFS" || fail 'replacement actions must refresh notification controls'
grep -Fq 'function onHasInlineReplyChanged() { root.scheduleTrackedNotificationRefresh(modelData) }' "$NOTIFS" || fail 'replacement inline-reply state must refresh notification controls'
grep -Fq 'function onHintsChanged() { root.scheduleTrackedNotificationRefresh(modelData) }' "$NOTIFS" || fail 'replacement hints must refresh notification controls'
grep -Fq 'function onHasActionIconsChanged() { root.scheduleTrackedNotificationRefresh(modelData) }' "$NOTIFS" || fail 'replacement action icon state must refresh notification controls'
grep -Fq 'function onResidentChanged() { root.scheduleTrackedNotificationRefresh(modelData) }' "$NOTIFS" || fail 'replacement resident behavior must refresh notification controls'
grep -Fq 'function onTransientChanged() { root.scheduleTrackedNotificationRefresh(modelData) }' "$NOTIFS" || fail 'replacement transient state must refresh notification controls'
grep -Fq 'function onInlineReplyPlaceholderChanged() { root.scheduleTrackedNotificationRefresh(modelData) }' "$NOTIFS" || fail 'replacement inline-reply placeholder must refresh notification controls' 
grep -Fq 'org.freedesktop.Notifications' "$ROOT/components/settings/sections/SettingsNotificationsSection.qml" || fail 'settings must explain D-Bus ownership while the module is disabled'
grep -Fq 'завершить Quickshell' "$ROOT/components/settings/sections/SettingsNotificationsSection.qml" || fail 'settings must explain how to release D-Bus name' 
grep -Fq 'NotificationComponents.Notifications {}' "$SHELL" || fail 'notification service component is not loaded by shell'
echo 'PASS: custom notification server stage 1 wiring'
